WILDCARD_MARK = "__wildcard__"

def resolve(name):
    try:
        for r in resolver.resolve(name, "A"):
            return str(r)
    except (dns.resolver.NXDOMAIN, dns.resolver.NoAnswer,
            dns.resolver.NoNameservers, dns.resolver.LifetimeTimeout):
        return None
    return None

def resolve_cname(name):
    try:
        return str(resolver.resolve(name, "CNAME")[0].target)
    except Exception:
